        p=line.rstrip('\\n').split('\\t')
        if p[1] in ids:
            sym[p[1]]=p[2]; chrm[p[1]]=p[6]
symbols=set(sym.values())
exons=collections.defaultdict(lambda: collections.defaultdict(list)); chroms={}; spans={}
with gzip.open('/workspace/ref/gencode.v47.annotation.gtf.gz','rt') as f:
    for line in f:
        if line.startswith('#'): continue
        p=line.rstrip('\\n').split('\\t')
        if len(p)<9 or p[2]"'!='"'exon': continue
        attrs=dict(item.split(' ',1) for item in p[8].rstrip(';').split('; ') if ' ' in item)
        gn=attrs.get('gene_name','').strip('\"')
        if gn not in symbols: continue
        tid=attrs.get('transcript_id','').split('.')[0]
        s=int(p[3]); e=int(p[4]); st=p[6]
        exons[gn][tid].append((s,e,st)); chroms[gn]=p[0]
        if gn not in spans: spans[gn]=[s,e]
        else: spans[gn]=[min(spans[gn][0],s),max(spans[gn][1],e)]
known=collections.defaultdict(set)
for gn,trs in exons.items():
    for tid,es in trs.items():
        es=sorted(set(es), key=lambda x:x[0])
        for a,b in zip(es,es[1:]):
            # observed = a.end-1, b.start-1, with small variants
            for ds in (-1,0,1):
                for de in (-1,0,1):
                    known[gn].add((a[1]-1+ds,b[0]-1+de))
# exon union per gene
exunion=collections.defaultdict(list)
for gn,trs in exons.items():
    ivs=[]
    for tid,es in trs.items():
        for s,e,st in es: ivs.append((s,e))
    ivs.sort()
    merged=[]
    for s,e in ivs:
        if merged and s<=merged[-1][1]+1:
            merged[-1]=(merged[-1][0],max(merged[-1][1],e))
        else: merged.append((s,e))
    exunion[gn]=merged
juncs=collections.defaultdict(list)
with open('/workspace/hisat2_novel_splicesites.tab') as f:
    for line in f:
        c,s,e,st=line.rstrip().split('\\t')
        juncs[c].append((int(s),int(e),st))
def overlap(ivs,s,e):
    return any(not (e<s or s2>e) for s2,e2 in ivs)
print('classic intronic cryptic exon candidates (top100):')
for gn in sorted(spans, key=lambda g:0):
